129	    /// Determine of the [`Type`] is a [subtype](https://en.wikipedia.org/wiki/Subtyping) of `other`.
130	    ///
131	    /// This should only be used at parse-time.
132	    /// If you have a concrete [`Value`](crate::Value) or [`PipelineData`](crate::PipelineData),
133	    /// you should use their respective `is_subtype_of` methods instead.
134	    pub fn is_subtype_of(&self, other: &Type) -> bool {
135	        // Structural subtyping
136	        let is_subtype_collection = |this: &[(String, Type)], that: &[(String, Type)]| {
137	            if this.is_empty() || that.is_empty() {
138	                true
139	            } else if this.len() < that.len() {
140	                false
141	            } else {
142	                that.iter().all(|(col_y, ty_y)| {
143	                    if let Some((_, ty_x)) = this.iter().find(|(col_x, _)| col_x == col_y) {
144	                        ty_x.is_subtype_of(ty_y)
145	                    } else {
146	                        false
147	                    }
148	                })
149	            }
150	        };
151	
152	        match (self, other) {
153	            (t, u) if t == u => true,
154	            (_, Type::Any) => true,
155	            // We want `get`/`select`/etc to accept string and int values, so it's convenient to
156	            // use them with variables, without having to explicitly convert them into cell-paths
157	            (Type::String | Type::Int, Type::CellPath) => true,
158	            (Type::OneOf(oneof), Type::CellPath) => {
159	                oneof.iter().all(|t| t.is_subtype_of(&Type::CellPath))
160	            }
161	            (Type::Float | Type::Int, Type::Number) => true,
162	            (Type::Glob, Type::String) | (Type::String, Type::Glob) => true,
163	            (Type::List(t), Type::List(u)) if t.is_subtype_of(u) => true, // List is covariant
164	            (Type::Record(this), Type::Record(that)) | (Type::Table(this), Type::Table(that)) => {
165	                is_subtype_collection(this, that)
166	            }
167	            (Type::Table(_), Type::List(that)) if matches!(**that, Type::Any) => true,
168	            (Type::Table(this), Type::List(that)) => {
169	                matches!(that.as_ref(), Type::Record(that) if is_subtype_collection(this, that))
170	            }
171	            (Type::List(this), Type::Table(that)) => {
172	                matches!(this.as_ref(), Type::Record(this) if is_subtype_collection(this, that))
173	            }
174	            (Type::OneOf(this), that @ Type::OneOf(_)) => {
175	                this.iter().all(|t| t.is_subtype_of(that))
176	            }
177	            (this, Type::OneOf(that)) => that.iter().any(|t| this.is_subtype_of(t)),
178	            _ => false,
179	        }
180	    }
